public final class MoreStreams {
    public static <T, R> BiConsumer<T, Consumer<R>> instanceOf(Class<R> type) {
        return (val, sink) -> {
            if (type.isInstance(val)) {
                sink.accept(type.cast(val));
            }
        };
    }
}

